function pick(A){let x=Math.random()*100,r=0;for(;r<5&&(x-=RP[r])>=0;r++);let l=A.filter(i=>i.r==r);while(!l.length)l=A.filter(i=>i.r==--r);return rnd(l)}
function pvpSetup(){app.innerHTML=back()+`<h2>PvP: monte seus piratas</h2><p>Raça, fruta e espada são sorteadas na hora, com as chances do gacha. Logia ignora golpes físicos, a menos que o atacante use Haki de Armamento.</p><div class="two">${picker(P[0],0,"pvpSetup","Jogador 1",0,0,2)+picker(P[1],1,"pvpSetup","Jogador 2",1,0,2)}</div><button class="big" onclick="pvpGo()">Sortear e lutar</button>`}
function next(){reviveIfPossible();const d=B.p.find(q=>q.hp<=0);
if(d){B.over=1;B.win=d==B.p[0]?1:0;B.log.push(`${B.p[B.win].n} venceu!`);return draw()}
B.t=1-B.t;let c=B.p[B.t];c.hk=Math.min(100,c.hk+(c.hkr||15));
if(c.stun){c.stun=0;B.log.push(`${c.n} está atordoado e perde a vez.`);B.t=1-B.t;c=B.p[B.t];c.hk=Math.min(100,c.hk+(c.hkr||15))}
draw();if(c.ai)setTimeout(ai,900)}
function ai(){const a=B.p[B.t];if(B.over||!a.ai||!$(".arena"))return;const L=acts(a);
if(a.hk>=30&&!a.arm&&Math.random()<.25)return hk(1);
if(a.hk>=30&&!a.obs&&Math.random()<.15)return hk(2);
if(a.f&&a.f.f&&a.tf<(a.f.forms||[a.f.f]).length&&Math.random()<.3)return hk(4);
const ok=L.map((x,i)=>i).filter(i=>L[i][3]<=a.hk);act(Math.random()<.6?ok.reduce((m,i)=>L[i][1]>L[m][1]?i:m):rnd(ok))}
let AC,mus=1,stp=0,tm,md=0;
